'use strict';
const R=RiskModel;
const RISK_CONTEXT={
 DXY:['美元偏强可能收紧全球美元流动性，并压制风险偏好。','核对美债利率与人民币是否同向；美元上涨不必然导致A股下跌。'],
 CNH:['USD/CNH上升代表离岸人民币走弱，影响外资风险偏好、进口成本及汇兑。','出口公司的外币收入与进口设备支出方向不同，需结合净敞口。'],
 US10Y:['美债收益率上行抬升全球折现率，科技长久期估值通常更敏感。','区分增长预期上修与通胀/期限溢价；收益率变化用bp，不称债券收益。'],
 DJI:['道指观察美国大型蓝筹与经济周期风险。','与纳指分化时，检查行业轮动，不能用道指替代科技景气。'],
 IXIC:['纳斯达克综合指数反映美国科技与成长股整体风险偏好。','需与SOXX、QQQ及公司经营交叉验证；成分存在重合。'],
 N225:['日经225观察日本风险偏好、半导体设备及日元相关传导。','本币指数未计汇率；关注设备供应链、出口限制及订单。'],
 KOSPI:['韩国综合指数对存储与电子周期较敏感，可辅助观察DRAM链。','综合指数不等于存储价格；长鑫科技仍需产品价格与扩产证据。'],
 SOX:['SOX为纳斯达克发布的PHLX半导体行业价格指数，用于观察半导体设计、制造与设备链交易风险。','与SOXX ETF的编制基准和成分权重不同；二者不互相替代，合计权重22%（SOX 12%、SOXX 10%）。'],
 usSOXX:['SOXX作为美股半导体价格代理，连接芯片、设备与制造链风险。','对中芯国际/长鑫科技观察行业共振；ETF涨跌不能替代利用率和现金流。'],
 usQQQ:['QQQ跟踪纳指100，观察大型成长股折现率及AI资本开支预期。','QQQ权重上调至14%，强化大型科技压力传导；与纳指、SOX/SOXX仍有相关性重叠。'],
 hkHSTECH:['恒生科技观察离岸中国科技风险偏好、流动性与盈利预期。','与A股科创50业务结构不同，观察相对变化，不机械同步。'],
 A50:['富时中国A50观察中国大盘股离岸定价与风险偏好。','本项是现货指数，不是A50期货；注意时区与期货基差。'],
 GOLD:['黄金连续期货同时受避险、实际利率与美元影响。','仅把剧烈变动与波动计为跨资产压力；不把上涨统一视为利空。'],
 SILVER:['白银同时具有贵金属与工业需求属性，波动通常较大。','结合黄金和工业周期；连续合约换月会影响长窗口变化。'],
 BTC:['比特币观察24小时高波动风险资产的杠杆与流动性压力。','周末仍交易；与A股传导关系不稳定，不直接映射涨跌。']
};
function riskState(r){return !E.valid(r.score)||r.coverage<.6?['证据不足','warn']:r.score>=80?['高关注','danger']:r.score>=60?['偏高','warn']:r.score>=30?['需关注','neutral']:['相对较低','good']}
function riskNumber(r){return E.valid(r.score)&&r.coverage>=.6?num(r.score,1):'—'}
function riskBadge(r){const [label,tone]=riskState(r);return `<span class="risk-badge">${pill(label,tone)} <b>${riskNumber(r)}</b><small>/100</small></span>`}
function riskCoverage(r){return `<div class="risk-coverage"><span>有效权重 ${num(r.coverage*100,0)}%</span><span>缺失边界 ${num(r.low,0)}–${num(r.high,0)}</span></div><div class="risk-track"><i style="width:${Math.round(r.coverage*100)}%"></i></div>`}
function riskCard(n,label,r,text,anchor){return `<a class="risk-card" href="#${anchor}" onclick="event.preventDefault();document.getElementById('${anchor}').scrollIntoView({behavior:'smooth',block:'start'})"><div class="risk-card-head"><span>0${n} / ${label}</span>${pill(riskState(r)[0],riskState(r)[1])}</div><strong class="risk-number">${riskNumber(r)}<small>/ 100</small></strong><p>${text}</p>${riskCoverage(r)}</a>`}
function riskPartsTable(parts){return `<div class="table-wrap"><table class="wrap-table"><thead><tr><th>分项</th><th>名义权重</th><th>关注分</th><th>有效覆盖</th><th>规则 / 证据时间</th></tr></thead><tbody>${parts.map(p=>`<tr><td>${esc(p.name)}</td><td>${num(p.weight,1)}</td><td>${E.valid(p.score)?num(p.score,1):'缺失'}</td><td>${E.valid(p.score)?num((p.coverage??1)*100,0)+'%':'0%'}</td><td>${esc(p.reason||'本层分数按下层有效权重传递')} ${esc(p.date||'')}</td></tr>`).join('')}</tbody></table></div>`}
function riskSnapshot(){const d=data(),ext=R.globalRisk(d.external,d.geopolitics),dom=R.domesticRisk(d.instruments,BENCH_CODES,ext),watch=WATCH_CODES.map(code=>{const a=byCode(code),parent=(a.market||'CN')==='CN'?dom:R.regionalRisk(ext,a.market);return {...R.watchRisk(d.instruments[code],a,parent),parentRisk:parent,parentLabel:({CN:'A股',HK:'港股',US:'美股'})[a.market||'CN']}}),group=R.aggregate(watch.map(r=>({...r,name:r.asset.name,weight:1})));return {d,ext,dom,watch,group}}
function externalChange(x,n){const r=x.returns?.[n];if(!E.valid(r?.value))return `<span class="muted" title="${esc(r?.reason||'历史不足或未接入')}">— 历史不足</span>`;return `<strong>${r.value>0?'+':''}${num(r.value)}${r.unit==='bp'?' bp':'%'}</strong><small class="table-sub">${esc(r.start)} → ${esc(r.end)}</small>`}
function externalRead(x){const m=x.model||R.technical(x.history,x.kind),s=RISK_CONTEXT[x.symbol];return `<p>${esc(s?.[0]||'辅助观察海外产业链风险偏好，不计入外围总分。')}</p><p class="muted">${x.kind==='yield'&&x.history?.length>20?`20日变动 ${num((x.history.at(-1).close-x.history.at(-21).close)*100)} bp；`:E.valid(m.ret20)?`20日${change(m.ret20)}，`:''}${x.kind!=='yield'&&E.valid(m.drawdown)?`近60日高点回撤${num(m.drawdown)}%；`:''}${esc(s?.[1]||'结合经营披露与国内相对走势验证。')}</p>${x.error||x.history_error?`<small class="risk-warning">本次${x.history_error?'历史':''}取数失败${x.retained||x.retained_history?'，保留上次可用数据':''}：${esc(x.error||x.history_error)}</small>`:''}`}

function geopoliticalPanel(geo){const fresh=R.fresh(geo?.as_of,14);return `<div class="grid-two risk-geo">${['politics','war'].map(kind=>{const item=(geo?.items||[]).find(x=>x.kind===kind),r=R.aggregate([R.leaf('',1,fresh?item?.score:null)]),war=kind==='war';return panel(war?'B2 · 战争 / 冲突风险':'B1 · 政治 / 地缘风险',`<div class="panel-body">${riskBadge(r)}<p class="risk-description">${war?'行动类新闻增多，可能通过能源、航运、保险和交付扰动传导。':'威胁类新闻增多，可能通过出口许可、投资审查和风险溢价传导。'}这是模型解释，不能据此确认具体战况或政策现状。</p><div class="definition-row"><span>${esc(item?.field||'GPR子项')} · 30日均值</span><strong>${num(item?.value30)}</strong></div><p class="small muted">${esc(geo?.as_of||'尚未抓取')} · 近3年${item?.baseline_count||0}个有效滚动均值 · 权重10%。政治广义风险未被新闻指数完整覆盖。</p>${war?`<div class="risk-source-event"><strong>已核实背景 · 2026-10-15</strong><p>联合国安理会声明涉及红海商业航运、能源设施与地区升级风险。对科技链需验证运价、运输路线及交付影响。</p>${sourceLink('https://mandates.un.org/mandate/S/PRST/2026/4?subject=Red+Sea','联合国声明 S/PRST/2026/4')}</div>`:`<div class="risk-source-event"><strong>历史政策背景 · 2026-01-13</strong><p>美国BIS曾调整部分对华半导体出口许可审查政策。此条仅作历史背景；当前许可范围与适用性须再查官方更新。</p>${sourceLink('https://media.bis.gov/press-release/department-commerce-revises-license-review-policy-semiconductors-exported-china','BIS原文')}</div>`}<small class="muted">背景核对日2026-11-01；不参与数值评分，不自动更新战况。GPR日频、每周更新、允许回修；超过14天停止计分。</small>${geo?.error?`<p class="risk-warning">GPR本次刷新失败：${esc(geo.error)}</p>`:''}</div>`)}).join('')}</div><div class="panel-note">量化口径：威胁/行动子项的30日均值，在近1095日有效滚动均值中计算历史分位（0–100）；至少252个样本。分位高表示新闻压力处于历史高位，不是政治事件或战争的发生概率。${sourceLink(geo?.url||'https://www.matteoiacoviello.com/gpr.htm','GPR官方数据与方法')} · Caldara & Iacoviello (2022), CC BY 4.0。</div>`}
function riskWatchCards(watch){return `<div class="risk-watch-grid">${watch.map(x=>`<article class="risk-stock"><div class="risk-stock-head"><div><button class="stock-link" onclick="setAsset('${x.code}','research')">${x.asset.name}</button><small>${x.code} · ${x.asset.industry}</small></div>${riskBadge(x)}</div>${riskCoverage(x)}<p>${x.price.date?'价格截至 '+esc(x.price.date):'价格证据不足'}${E.valid(x.price.ret20)?' · 20日 '+change(x.price.ret20):''}</p><div class="risk-contributors"><span>自身 ${riskNumber(x.local)} ×75%</span><span>${x.parentLabel} ${riskNumber(x.parentRisk)} ×25%</span></div><details class="risk-details"><summary>七维评分、缺失项与依据</summary>${riskPartsTable(x.local.parts)}<div class="panel-note">${provenance(ctx(x.code))} ${button('打开七维研究',`setAsset('${x.code}','research')`,false)}</div></details></article>`).join('')}</div>`}
function riskOverview(){const {d,ext,dom,watch,group}=riskSnapshot();return title('风险总览','从全球压力到A股结构，再到每一只自选。分数越高，需关注的风险越多。',button('查看评分方法',"document.getElementById('risk-method').scrollIntoView({behavior:'smooth'})",false,'info'))+`<div class="risk-hero"><div><span class="risk-eyebrow">RISK TRANSMISSION / 风险传导</span><h2>把风险放在同一张地图上</h2><p>外围分项加权 → A股本地70% + 外围30% → 自选自身75% + 对应市场25%</p></div><div class="risk-model-tag">研究模型 v1.1<small>非概率 · 权重尚未实证校准</small></div></div><div class="risk-cards">${riskCard(1,'外围风险',ext,'15类跨市场资产80% + 政治10% + 战争10%','risk-external')}${riskCard(2,'A股指数风险',dom,'六ETF本地风险70% + 外围风险30%','risk-domestic')}${riskCard(3,'自选风险',group,WATCH_CODES.length+'只自选综合风险等权观察；非账户持仓风险','risk-watch')}</div><p class="risk-caption">分数按已知有效权重暂估；有效权重不足60%时隐藏点分。边界假设缺失项分别为0/100，不是置信区间。各市场日频时间不同，均以行内日期为准。</p>${isDemo()?notice('当前为合成演示：A股分数仅演示规则；外围及GPR未伪造样本。请连接本地数据后刷新。'):''}<section id="risk-external" class="risk-section">${panel('01 · 外围风险',`<div class="panel-body risk-section-intro"><div><h3>A · 跨市场资产压力</h3><p>美元/人民币/美债15% · 海外股票50%（纳指8%、SOX 12%、SOXX 10%、QQQ 14%） · 离岸中国8% · 贵金属/比特币7%。股指用下行、趋势和波动；汇率/利率以上行压力；贵金属用绝对冲击。</p></div>${riskBadge(ext)}</div>${riskExternalDisplay(ext.assets)}${riskGeopoliticalDisplay(d.geopolitics)}`,riskLayoutControl('external'))}</section><section id="risk-domestic" class="risk-section">${panel('02 · A股指数风险',`<div class="panel-body risk-section-intro"><div><h3>六类ETF等权，保留风格差异</h3><p>六ETF本地分 ${riskNumber(dom.local)} ×70% + 外围分 ${riskNumber(ext)} ×30%；缺失有效权重逐层折减。全部为ETF价格代理，未计分红总回报。</p></div>${riskBadge(dom)}</div>${riskDomesticDisplay(dom.rows)}<div class="panel-body">${finding('科技链的传导需要二次确认',`${marketConclusion().label}。SOX、SOXX/韩国市场用于观察半导体风险，QQQ/纳指用于观察AI与成长风险，人民币和美债用于观察流动性与折现率。`,'结合六ETF相对走势、公司订单、利用率及现金流；模型加权反映研究关注程度，不代表统计因果关系。')}</div><details class="risk-details"><summary>展开本层权重及覆盖</summary>${riskPartsTable(dom.parts)}</details>`,riskLayoutControl('domestic'))}</section><section id="risk-watch" class="risk-section">${panel('03 · 自选风险',`<div class="panel-body"><p class="risk-description">每只标的：自身七维75% + 对应市场风险25%（A股六ETF、港股离岸中国代理、美股科技及宽基代理）。自身权重为趋势20%、经营/成分20%、估值10%、资金10%、波动15%、回撤15%、治理事件10%。ETF改用成分集中度、同日净值及申赎口径。</p></div>${riskWatchDisplay(watch)}`,riskLayoutControl('watch'))}</section>${riskMethod()}`}
function riskMethod(){return `<section id="risk-method" class="risk-section">${panel('评分方法与适用边界',`<div class="panel-body"><h3>0–100关注分，不是亏损概率</h3><p class="risk-description">0–30相对较低，30–60需关注，60–80偏高，80–100高关注。阈值与权重均为可审查的研究假设，尚未经过样本外校准；本页实时快照评分不回填历史回测，也不自动下单。</p><details class="risk-details"><summary>资产评分公式与时效</summary><div class="risk-method-copy"><p>股票/ETF：趋势30%（低于MA20与MA60各50分）+20日下行25%（跌15%封顶100）+近60日最高收盘回撤25%（回撤25%封顶）+20日收益标准差年化波动20%（60%封顶；比特币100%）。年化天数股票252、比特币365。</p><p>美元/人民币/利率：上行趋势50%（高于MA20、MA60各50分）+20日上行压力30%（美元/人民币升5%，美债升50bp封顶）+波动20%（年化20%或利率日变化标准差10bp封顶）。人民币报价为USD/CNH，数值上升代表人民币走弱。黄金/白银：20日绝对涨跌冲击50%（15%封顶）+年化波动50%（60%封顶）。</p><p>自身七维与外围资产模型的权重分别计算。自选经营项内部：收入下降压力30%（降30%封顶）、现金兑现50%（正净利条件下，1−经营现金/净利）、负债20%（资产负债率80%封顶）。资金项近5条大单净流出5亿元封顶。ETF前十持仓占净值直接映射集中关注分；同日净值偏离3%封顶。负净利的现金兑现不适用，保留缺失。</p><p>价格超过7个自然日（比特币2日）、财报披露/ETF报告期超过220日、GPR超过14日，停止计入相应维度。收盘前价格可变，图中及表内标明盘中。估值缺同行/历史分位、治理缺原文影响判断时保持缺失；不把没有公告视为零风险。</p></div></details><details class="risk-details"><summary>缺失权重如何层层传递</summary><div class="risk-method-copy"><p>有效权重=名义权重×下层覆盖率；暂估分=Σ(有效权重×分项分)/Σ有效权重。覆盖率=Σ有效权重/Σ名义权重。上层使用相同公式继续传播，不将不完整的外围分视作完整证据。</p><p>缺失边界下限=Σ(有效权重×分项分)/总权重，上限=下限+100×缺失比例。边界宽说明证据不足，不用于构造虚假的精确结论。外围与A股权重有相关性；本模型尚未估计跨市场贝塔与滞后影响。</p></div></details></div>`)}</section>`}
function externalV6(){const rows=data().external||[];return `<div class="grid-two">${panel('外围表现与产业传导',`<div class="panel-body">${finding('把短期情绪与中长期变化分开','最近60日与250日按相应标的有效日频观察值计算：末值÷60/250个间隔前价格−1；需要61/251条日线。不填补停牌或节假日，不将年内收益当250日收益。','半导体观察SOXX及美光/台积电，算力互联观察QQQ/英伟达/博通；国内公司仍需订单、盈利和经营现金流证据。')}${button('查看完整风险传导',"go('overview')",true)}</div>`)}${panel('比较口径',`<div class="panel-body"><p class="risk-description">美债收益率使用基点变化；黄金/白银为连续期货价格代理，包含换月影响。ETF与股指为价格变化，不含现金分红总回报；美元报价未换算人民币。比特币包含周末观察值，跨市场窗口的日历长度不同。末根若盘中将随刷新变化。</p></div>`)}</div>${externalMarketTable(rows)}`}
function strategyExplanation(){return panel('策略解释 · 三因子增强与六ETF走弱过滤',`<div class="panel-body"><div class="grid-two strategy-help"><div><div class="chip-line">${pill('三因子增强',bt.enhanced?'good':'neutral')}${pill(bt.enhanced?'当前已启用':'当前未启用','neutral')}</div><h3>给金叉增加量价与资金验证</h3><p>基础信号来自三重EMA：买入用N=3/3，卖出用N=5/5。增强模式用资金流入、量价背离、布林带宽扩张共同打分；A/B级买入分数低于−0.5则跳过。资金缺失时不凑分，保留基础信号。</p><details class="risk-details"><summary>展开三因子公式与附加信号</summary><p>资金因子 M=clip(当日大单净额÷5亿元, −2, 2)，权重40%；量价因子 D 比较5日前：价涨量缩=−1、价跌量缩=+1、价量齐升=0.5，其余=0，权重30%；带宽扩张 X=当前布林带宽÷此前20日平均带宽，权重30%。布林带宽=4×20日收盘标准差÷MA20。</p><div class="risk-formula">Score = 0.4M + 0.3D + 0.3(X−1)×2</div><p>增强还可能提前生成信号：净流入&gt;2亿元、POS≥0.8、量比≥1、|SHORTL−MIDL|&lt;6时提前买入；N3死叉且净流出&lt;−3亿元时提前卖出。POS是收盘在日内高低区间的位置。以上为本版研究阈值，波动扩张既可能伴随上涨也可能伴随下跌，分高不保证盈利。</p></details></div><div><div class="chip-line">${pill('六ETF走弱过滤',bt.marketGate?'good':'neutral')}${pill(bt.marketGate?'当前已启用':'当前未启用','neutral')}</div><h3>先看市场环境，再决定是否新增模拟</h3><p>沪深300ETF、中证A500ETF、中证500ETF、中证1000ETF、创业板ETF、科创50ETF，分别用历史信号日收盘价比较当日MA10。至少4/6低于MA10时，跳过该笔新增买入；卖出继续按原规则执行。任一ETF缺历史或MA10，也跳过新增买入。</p><details class="risk-details"><summary>展开回测时序与适用边界</summary><p>使用信号当日以前已确认收盘的ETF数据，禁止拿今天的市场状态回填历史。过滤是暂停新增模拟，不是自动卖出或按级减仓；不同于技能原始四指数≥3只走弱版本。</p><p>两个开关可独立比较。信号收盘后形成订单，次日开盘或按信号收盘价±限价模拟；未穿价保留未成交，不事后回到同日开盘追单。绩效含所设成本与滑点。风险总览新评分仅供当前研究，不会自动改变历史策略。</p></details></div></div><p class="small muted">基础A/B使用相同研究仓位，C级跳过，卖出统一平仓。当前开关状态已与左侧研究参数同步；改变后自动重算订单、信号及图表。六ETF过滤仅用于A股；港美股按各自市场日期、交易币种和1股研究单位独立回测。</p></div>`,'','panel-space')}
window.overview=riskOverview;window.externalV4=externalV6;

// Presentation state is independent for each risk block and each sortable table.
const RISK_TABLE_COLUMNS={
 external:['name','weight','price','change','ret5','ret20','ret60','ret250','risk','coverage','date'],
 domestic:['name','price','change','ret20','ret60','volatility','risk','coverage','date'],
 watch:['name','market','risk','coverage','local','parent','ret20','date'],
 geopolitical:['name','weight','risk','value','date'],
 externalMarket:['name','price','change','ret60','ret250','date'],
 researchPool:['name','ret20','revenue','profit','cash','ratio','period'],
 marketBench:['name','price','change','ret20','ret60','volatility','trend','date'],
 marketSector:['name','price','change','ret20','ret60','drawdown','trend','date']
};
const RISK_LAYOUT_LABELS={external:'外围风险',domestic:'A股指数风险',watch:'自选风险'};
function riskLayout(group){return state.riskLayouts?.[group]==='table'?'table':'cards'}
function riskLayoutControl(group){return `<div class="risk-view-switch" role="group" aria-label="${RISK_LAYOUT_LABELS[group]}展示方式">${[['cards','卡片'],['table','表格']].map(([value,label])=>`<button data-risk-view="${group}-${value}" aria-pressed="${riskLayout(group)===value}" onclick="setRiskLayout('${group}','${value}')">${icon(value==='cards'?'nodes':'settings')}${label}</button>`).join('')}</div>`}
function setRiskLayout(group,layout){
 if(!RISK_LAYOUT_LABELS[group]||!['cards','table'].includes(layout))return;
 const section=document.getElementById('risk-'+group),top=section?.getBoundingClientRect().top;
 state.riskLayouts={...state.riskLayouts,[group]:layout};render();
 const updated=document.getElementById('risk-'+group);
 if(updated&&Number.isFinite(top))window.scrollBy(0,updated.getBoundingClientRect().top-top);
 document.querySelector(`[data-risk-view="${group}-${layout}"]`)?.focus({preventScroll:true});
}
function visibleRiskValue(model){return model&&E.valid(model.score)&&model.coverage>=.6?model.score:null}
function sortedRiskRows(rows,table,sort=state.riskSorts?.[table]){
 if(!sort||!RISK_TABLE_COLUMNS[table]?.includes(sort.key)||!['asc','desc'].includes(sort.direction))return rows.slice();
 const missing=v=>v==null||v===''||typeof v==='number'&&!Number.isFinite(v),sign=sort.direction==='asc'?1:-1;
 return rows.map((row,index)=>({row,index,value:row.values[sort.key]})).sort((a,b)=>{
  const am=missing(a.value),bm=missing(b.value);if(am||bm)return am===bm?a.index-b.index:am?1:-1;
  const delta=typeof a.value==='number'&&typeof b.value==='number'?a.value-b.value:String(a.value).localeCompare(String(b.value),'zh-CN',{numeric:true,sensitivity:'base'});
  return sign*delta||a.index-b.index;
 }).map(x=>x.row);
}
function riskTableHeader(table,key,label,hint=''){
 if(!key)return `<th scope="col">${esc(label)}</th>`;
 const active=state.riskSorts?.[table]?.key===key,direction=active?state.riskSorts[table].direction:null,next=direction==='asc'?'降序':'升序';
 return `<th scope="col" aria-sort="${active?(direction==='asc'?'ascending':'descending'):'none'}"><button class="risk-sort-button ${active?'active':''}" data-risk-sort="${table}-${key}" onclick="toggleRiskSort('${table}','${key}')" aria-label="${esc(label)}，点击${next}排列" title="${esc(hint||label)}；点击${next}">${esc(label)}<span aria-hidden="true">${direction==='asc'?'↑':direction==='desc'?'↓':'↕'}</span></button></th>`;
}
function toggleRiskSort(table,key){
 if(!RISK_TABLE_COLUMNS[table]?.includes(key))return;
 const old=state.riskSorts?.[table];state.riskSorts={...state.riskSorts,[table]:{key,direction:old?.key===key&&old.direction==='asc'?'desc':'asc'}};
 const left=document.querySelector(`[data-risk-table="${table}"]`)?.scrollLeft||0,x=window.scrollX,y=window.scrollY;
 render();const wrap=document.querySelector(`[data-risk-table="${table}"]`);if(wrap)wrap.scrollLeft=left;
 window.scrollTo(x,y);document.querySelector(`[data-risk-sort="${table}-${key}"]`)?.focus({preventScroll:true});
}
function riskDataTable(table,label,columns,rows,extraClass=''){
 const sorted=sortedRiskRows(rows,table);
 return `<div class="table-wrap risk-data-wrap" data-risk-table="${table}"><table class="risk-data-table ${extraClass}" aria-label="${esc(label)}"><thead><tr>${columns.map(([key,title,hint])=>riskTableHeader(table,key,title,hint)).join('')}</tr></thead><tbody>${sorted.map(row=>`<tr>${row.cells.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${columns.length}" class="empty">暂无可用标的，缺失数据不会补造。</td></tr>`}</tbody></table></div><p class="risk-sort-note">点击表头切换升序 / 降序；缺失值始终置后，同值保持原顺序。${table==='researchPool'?'经营现金按各自报告币种的原始金额排序，未换汇；报告期与累计/年度口径不同，请逐项核对。':table.startsWith('market')?'ETF为价格代理，不含分红再投资；盘中末根会随行情刷新变化。':'关注分覆盖不足60%不展示、不参与数值排名。价格按原单位数值排序，不换汇。外围变化列按展示数值排序，bp与%不可视作同口径收益排名。'}</p>`;
}
function riskReturnCell(x,n){const r=x.returns?.[String(n)];return `<span class="num ${cls(r?.value)}">${E.valid(r?.value)?(r.value>0?'+':'')+num(r.value)+(r.unit==='bp'?' bp':'%'):'—'}</span>`}
function riskDateCell(x){return `${esc(x.history_as_of||x.timestamp||'未返回')}<small class="table-sub">${esc(x.timezone||'日频')}${x.provisional?' · 盘中快照':''}</small>${x.url?sourceLink(x.url,'来源'):''}`}
function riskExternalTable(assets){
 const columns=[['name','外围标的'],['weight','权重'],['price','价格 / 单位'],['change','最近一日'],['ret5','5日变化'],['ret20','20日变化'],['ret60','60日变化'],['ret250','250日变化'],['risk','关注分'],['coverage','有效覆盖'],['date','观察日期 / 来源'],[null,'解读与依据']];
 const rows=assets.map(x=>({values:{name:x.name,weight:x.weight,price:x.price,change:x.change,ret5:x.returns?.['5']?.value,ret20:x.returns?.['20']?.value,ret60:x.returns?.['60']?.value,ret250:x.returns?.['250']?.value,risk:visibleRiskValue(x.model),coverage:x.model?.coverage,date:x.history_as_of||x.timestamp},cells:[
 `<strong>${esc(x.name)}</strong><small class="table-sub">${esc(x.ticker||x.symbol)}</small>`,num(x.weight,0)+'%',`${num(x.price,x.symbol==='CNH'?4:2)}<small class="table-sub">${esc(x.unit||'—')}</small>`,`<span class="num ${cls(x.change)}">${change(x.change)}</span>`,...[5,20,60,250].map(n=>riskReturnCell(x,n)),riskBadge(x.model),num(x.model.coverage*100,0)+'%',riskDateCell(x),`<button class="risk-detail-link" aria-haspopup="dialog" onclick="openExternalRiskDetails('${x.symbol}')">解读与评分依据</button>`]}));
 return riskDataTable('external','外围资产风险表',columns,rows,'risk-table');
}
function riskExternalDisplay(assets){return riskLayout('external')==='cards'?globalAssetCards(assets):globalAssetControls(assets)+riskExternalTable(selectedGlobalAssets(assets))}
function riskGeopoliticalDisplay(geo){
 if(riskLayout('external')==='cards')return geopoliticalPanel(geo);
 const fresh=R.fresh(geo?.as_of,14),rows=['politics','war'].map(kind=>{const item=geo?.items?.find(x=>x.kind===kind),model=R.aggregate([R.leaf('',1,fresh?item?.score:null)]),war=kind==='war',name=war?'战争 / 冲突风险':'政治 / 地缘风险';return {values:{name,weight:10,risk:visibleRiskValue(model),value:item?.value30,date:geo?.as_of},cells:[`<strong>${name}</strong><small class="table-sub">${esc(item?.field||'GPR子项')}</small>`,'10%',riskBadge(model),num(item?.value30),esc(geo?.as_of||'未返回'),war?'行动类新闻压力，通过能源、航运与交付扰动传导。':'威胁类新闻压力，通过出口许可、投资审查与风险溢价传导。']}});
 return `<div class="risk-geo-table"><h3>B · 政治与战争风险</h3>${riskDataTable('geopolitical','政治与战争风险表',[['name','分项'],['weight','权重'],['risk','关注分'],['value','30日均值'],['date','数据日期'],[null,'解读']],rows)}<details class="risk-row-details risk-geo-full"><summary>政治与战争风险的完整解读、背景与来源</summary>${geopoliticalPanel(geo)}</details></div>`;
}
function riskDomesticDisplay(riskRows){
 if(riskLayout('domestic')==='cards')return benchmarkCards(null,riskRows);
 const rows=riskRows.map(x=>{const a=byCode(x.code),bars=series(x.code),m=E.metrics(bars),date=bars.at(-1)?.date;return {values:{name:a.shortName||a.name,price:m?.price,change:m?.change,ret20:m?.ret20,ret60:m?.ret60,volatility:m?.vol20,risk:visibleRiskValue(x.model),coverage:x.model.coverage,date},cells:[`<button class="stock-link" onclick="openBenchmark('${x.code}')">${esc(a.shortName||a.name)}</button><small class="table-sub">${x.code} · 本地权重1/6</small>`,num(m?.price,3),`<span class="${cls(m?.change)}">${change(m?.change)}</span>`,`<span class="${cls(m?.ret20)}">${change(m?.ret20)}</span>`,`<span class="${cls(m?.ret60)}">${change(m?.ret60)}</span>`,change(m?.vol20),riskBadge(x.model),num(x.model.coverage*100,0)+'%',esc(date||'未返回')+(bars.at(-1)?.completed===false?' · 盘中':''),`<details class="risk-row-details"><summary>评分依据</summary>${riskPartsTable(x.model.parts)}</details>${button('查看K线',`setAsset('${x.code}','backtest')`)} `]}});
 return riskDataTable('domestic','A股指数风险表',[['name','六类ETF'],['price','价格（元）'],['change','日涨跌'],['ret20','20日涨跌'],['ret60','60日涨跌'],['volatility','20日年化波动'],['risk','本地关注分'],['coverage','有效覆盖'],['date','数据日期'],[null,'依据 / 研究']],rows);
}
function riskWatchDisplay(watch){
 if(riskLayout('watch')==='cards')return riskWatchCards(watch);
 const rows=watch.map(x=>({values:{name:x.asset.name,market:x.parentLabel,risk:visibleRiskValue(x),coverage:x.coverage,local:visibleRiskValue(x.local),parent:visibleRiskValue(x.parentRisk),ret20:x.price.ret20,date:x.price.date},cells:[`<a class="risk-watch-asset" href="${esc(researchHref(x.code))}" aria-label="${esc(x.asset.name)} · 打开个股七维分析"><strong>${esc(x.asset.name)}</strong><small class="table-sub">${esc(x.code)} · ${esc(x.asset.industry||'')}</small></a>`,esc(x.parentLabel),riskBadge(x),num(x.coverage*100,0)+'%',riskNumber(x.local),riskNumber(x.parentRisk),`<span class="${cls(x.price.ret20)}">${change(x.price.ret20)}</span>`,esc(x.price.date||'未返回'),`<button class="risk-detail-link" aria-haspopup="dialog" onclick="openWatchRiskDetails('${x.code}')">七维评分、缺失项与依据</button>`]}));
 return riskDataTable('watch','自选风险表',[['name','自选标的'],['market','市场'],['risk','综合关注分'],['coverage','有效覆盖'],['local','自身分（75%）'],['parent','市场分（25%）'],['ret20','20日表现'],['date','价格日期'],[null,'七维依据']],rows);
}
function externalMarketTable(assets){
 const rows=assets.map(x=>({values:{name:x.name,price:x.price,change:x.change,ret60:x.returns?.['60']?.value,ret250:x.returns?.['250']?.value,date:x.history_as_of||x.timestamp},cells:[`<strong>${esc(x.name)}</strong><small class="table-sub">${esc(x.ticker||x.symbol)}</small>`,`${num(x.price)}<small class="table-sub">${esc(x.unit||'')}</small>`,`<span class="${cls(x.change)}">${change(x.change)}</span>`,externalChange(x,'60'),externalChange(x,'250'),riskDateCell(x)+`<small class="table-sub">${x.history?.length||0}条日线</small>`+pill(R.fresh(x.history_as_of,x.kind==='crypto'?2:7)?(x.provisional?'盘中快照':'日频快照'):'缺失 / 过期',R.fresh(x.history_as_of,x.kind==='crypto'?2:7)?'good':'warn'),`<div class="risk-explain">${externalRead(x)}</div>`]}));
 return `<section class="panel">${riskDataTable('externalMarket','外围标的表',[['name','外围标的'],['price','价格'],['change','最近一日'],['ret60','最近60日收益 / bp'],['ret250','最近250日收益 / bp'],['date','观察日期 / 来源'],[null,'解读']],rows,'external-returns')}</section>`;
}

function openWatchRiskDetails(code){
 const x=riskSnapshot().watch.find(item=>item.code===code);if(!x)return;
 const dialog=document.getElementById('dialog');if(dialog.open)dialog.close();
 dialog.dataset.kind='risk-details';dialog.setAttribute('aria-label',x.asset.name+' · 七维评分、缺失项与依据');
 dialog.innerHTML=`<div class="dialog-head"><div><h2>${esc(x.asset.name)} · 七维评分</h2><p>${esc(x.code)} · ${esc(x.asset.industry||'')} · ${esc(x.parentLabel)}</p></div><button class="icon-button" autofocus aria-label="关闭七维评分弹窗" onclick="document.getElementById('dialog').close()">${icon('close')}</button></div><div class="dialog-body risk-dialog-body"><div class="risk-dialog-summary"><span>综合关注分</span>${riskBadge(x)}</div>${riskCoverage(x)}<p class="risk-description">自身 ${riskNumber(x.local)} ×75% + ${esc(x.parentLabel)}市场 ${riskNumber(x.parentRisk)} ×25%。以下为自身七维分项；缺失证据不会按零风险处理。</p><h3>七维分项与缺失依据</h3>${riskPartsTable(x.local.parts)}<p class="risk-description">分数为研究关注程度，不是亏损概率。有效覆盖不足60%时隐藏综合点分；各分项按行内证据日期核对。</p>${provenance(ctx(x.code))}</div><div class="risk-dialog-actions"><button class="btn" onclick="document.getElementById('dialog').close()">关闭</button><button class="btn primary" onclick="document.getElementById('dialog').close();setAsset('${x.code}','research')">打开七维研究</button></div>`;
 dialog.showModal();
}

function openExternalRiskDetails(symbol){
 const x=riskSnapshot().ext.assets.find(item=>item.symbol===symbol);if(!x)return;
 const dialog=document.getElementById('dialog');if(dialog.open)dialog.close();
 dialog.dataset.kind='risk-details';dialog.setAttribute('aria-label',x.name+' · 解读与评分依据');
 dialog.innerHTML=`<div class="dialog-head"><div><h2>${esc(x.name)} · 解读与评分依据</h2><p>${esc(x.ticker||x.symbol)} · 权重 ${num(x.weight,0)}% · ${esc(x.history_as_of||'日期缺失')}</p></div><button class="icon-button" autofocus aria-label="关闭解读与评分依据弹窗" onclick="document.getElementById('dialog').close()">${icon('close')}</button></div><div class="dialog-body risk-dialog-body"><div class="risk-dialog-summary"><span>资产关注分</span>${riskBadge(x.model)}</div>${riskCoverage(x.model)}<div class="risk-dialog-reading">${externalRead(x)}</div><h3>评分分项与缺失依据</h3>${riskPartsTable(x.model.parts)}<p class="risk-description">有效覆盖不足60%时隐藏点分。评分为研究关注程度，不是亏损概率；各市场日频日期不同，盘中数据会变化。</p><div class="provenance">${riskDateCell(x)}${x.history_url?' · '+sourceLink(x.history_url,'历史日线来源'):''}${x.symbol==='SOX'?' · '+sourceLink('https://indexes.nasdaq.com/Index/Overview/sox','Nasdaq指数说明'):x.symbol==='usSOXX'?' · '+sourceLink('https://www.ishares.com/us/products/239705/fund','iShares基金说明'):''}</div></div><div class="risk-dialog-actions"><button class="btn" onclick="document.getElementById('dialog').close()">关闭</button></div>`;
 dialog.showModal();
}
